import base64, zlib, json, urllib.request, hashlib, concurrent.futures, subprocess, sys
from pathlib import Path
package = json.loads(zlib.decompress(base64.b64decode('')))
remote = Path('/content/UROP_OFFICIAL_6WAY_TEXT')
remote.mkdir(exist_ok=True)
(remote/'protocol.json').write_text(package['config'])
(remote/'train_official_text.py').write_text(package['source'])
cfg = json.loads(package['config'])
data = remote/'data'; data.mkdir(exist_ok=True)
def prepare(info):
    target = data/info['filename']
    if target.exists() and hashlib.sha256(target.read_bytes()).hexdigest() == info['sha256']:
        return str(target)
    url = 'https://drive.usercontent.google.com/download?id='+info['drive_id']+'&export=download&confirm=t'
    request = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    tmp = target.with_suffix('.tsv.part')
    with urllib.request.urlopen(request, timeout=300) as response, tmp.open('wb') as output:
        while True:
            block=response.read(1024*1024)
            if not block: break
            output.write(block)
    if hashlib.sha256(tmp.read_bytes()).hexdigest() != info['sha256']:
        raise RuntimeError('Dataset checksum failed: '+info['filename'])
    tmp.replace(target)
    print('Verified:', info['filename'], info['rows'], flush=True)
    return str(target)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
    list(pool.map(prepare, cfg['splits'].values()))
backup = Path('/content/drive/MyDrive/Colab Notebooks/UROP/official_text_runs')
backup.mkdir(parents=True, exist_ok=True)
print('Dataset ready. Permanent evidence/checkpoints:', str(backup))
